actions.script:
const portal=ec.resource.script('component://mr-pass/screen/Shared/Portal.js'),p=ec.web.parameters
const token=p.token || null,invoiceId=token ? null : p.invoiceId || null
const base=publicPath.replace(/\/pay$/,'')
const query=(values)=>'?'+Object.entries(values).filter(([k,v])=>v)
    .map(([k,v])=>k+'='+encodeURIComponent(v)).join('&')
const out=portal.attempt('startInvoicePayment',{siteId:resolvedSiteId,token,invoiceId,
    operationId:p.operationId,confirm:['true','on'].includes(String(p.confirm))})
if(out.error){
    ec.web.sessionAttributes.passPayError=out.error.message
    ec.web.response.sendRedirect(base+query({token,invoiceId}))
    return
}
const attemptId=out.result.attempt.attemptId
// the gateway's return carries no token: the session remembers which link this attempt came from
if(token)ec.web.sessionAttributes['passPayToken.'+attemptId]=token
ec.web.response.sendRedirect(base+query({token,invoiceId,attemptId}))

// Only the attempt and its reference are read; anything else the gateway or the browser adds is ignored. The
// reference reads this attempt without the session (another device, an expired session); the session's link,
// when it has one, shows the invoice with it.
const clean=(value)=>String(value || '').replace(/[^A-Za-z0-9_-]/g,'').slice(0,64)
const attemptId=clean(ec.web.parameters.attemptId),key=clean(ec.web.parameters.key)
const token=attemptId ? ec.web.sessionAttributes['passPayToken.'+attemptId] || null : null
const base=publicPath.replace(/\/return$/,'')
ec.web.response.sendRedirect(base+'?attemptId='+encodeURIComponent(attemptId)
    +(key?'&key='+encodeURIComponent(key):'')+(token?'&token='+encodeURIComponent(token):''))

const portal=ec.resource.script('component://mr-pass/screen/Shared/Portal.js'),p=ec.web.parameters
token=p.token || null
returnKey=p.key || null
payError=ec.web.sessionAttributes.passPayError || null
shareUrl=ec.web.sessionAttributes.passShareUrl || null
if(payError)ec.web.sessionAttributes.remove('passPayError')
if(shareUrl)ec.web.sessionAttributes.remove('passShareUrl')
attempt=null;failure=null;view=null
let invoiceId=token ? null : p.invoiceId || null,resultInvoice=null
if(p.attemptId){
    const found=portal.attempt('getPaymentResult',
        {siteId:resolvedSiteId,attemptId:String(p.attemptId),token:returnKey ? null : token,returnKey})
    if(found.error)failure=found.error
    else{
        attempt=found.result.attempt;resultInvoice=found.result.invoice
        if(!token && !invoiceId && siteInfo.authenticated)invoiceId=resultInvoice.invoiceId
    }
}
if(!failure){
    const found=token || invoiceId ? portal.attempt('getInvoice',{siteId:resolvedSiteId,token,invoiceId}) : null
    if(found?.result){view=found.result;if(!attempt)attempt=view.attempt}
    // the gateway return's reference shows the attempt and its invoice, and offers nothing else
    else if(resultInvoice)view={invoice:resultInvoice,attempt:null,capabilities:{canPay:false,canShare:false}}
    else if(found?.error)failure=found.error
    else failure={kind:'NotFound',message:'Open the link in your invoice email to see the invoice.'}
}
payOperationId=portal.operationId()
